/**
 * Cinejoy webOS - Home View Controller (Modernized UI-M2)
 * File: app/js/views/home.js
 * Standard: 10-Foot Television UX, webOS 8.5.0 (Chromium ~108+)
 * Google TV Cinema Aesthetic: 14px Card Radii, #26292f Surface, Zero DOM Sinks
 */

(function (global) {
  'use strict';

  // SVG Helper with zero DOM sinks (no innerHTML / outerHTML)
  function createSvgElement(tag, attrs) {
    var el = document.createElementNS('http://www.w3.org/2000/svg', tag);
    if (attrs) {
      for (var key in attrs) {
        if (Object.prototype.hasOwnProperty.call(attrs, key)) {
          el.setAttribute(key, attrs[key]);
        }
      }
    }
    return el;
  }

  function createStarSvg(width, height) {
    var w = width ? String(width) : '12';
    var h = height ? String(height) : '12';
    var svg = createSvgElement('svg', {
      viewBox: '0 0 24 24',
      width: w,
      height: h,
      fill: 'currentColor'
    });
    var polygon = createSvgElement('polygon', {
      points: '12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2'
    });
    svg.appendChild(polygon);
    return svg;
  }

  // Shared Card Factory
  var CardFactory = global.CardFactory || {
    createSvgElement: createSvgElement,
    createStarSvg: createStarSvg,

    createPosterCard: function (item, groupName, index, options) {
      if (!item) return document.createComment('empty-card');
      var opts = options || {};
      var card = document.createElement('div');
      card.className = 'card-poster';
