      // Default "All" pill
      var defaultPill = document.createElement('button');
      defaultPill.className = 'filter-pill' + (!self.state.activeGenreId ? ' active' : '');
      defaultPill.setAttribute('data-nav', 'true');
      defaultPill.setAttribute('data-nav-group', self.mediaType + '-filter');
      defaultPill.setAttribute('data-nav-default', 'true');
      defaultPill.textContent = self.mediaType === 'tv' ? 'All Shows' : 'All Movies';
      fragment.appendChild(defaultPill);

      // Top genres
      var topGenres = genres.slice(0, 9);
      for (var i = 0; i < topGenres.length; i++) {
        var g = topGenres[i];
        var pill = document.createElement('button');
        var isActive = self.state.activeGenreId === g.id;
        pill.className = 'filter-pill' + (isActive ? ' active' : '');
        pill.setAttribute('data-nav', 'true');
        pill.setAttribute('data-nav-group', self.mediaType + '-filter');
        pill.setAttribute('data-genre-id', String(g.id));
        pill.textContent = g.name;
        fragment.appendChild(pill);
      }

      while (self.filterBar.firstChild) {
        self.filterBar.removeChild(self.filterBar.firstChild);
      }
      self.filterBar.appendChild(fragment);
    }).catch(function (err) {
      console.error('[CatalogViewController] Failed to load genres:', err);
    });
  };

  CatalogViewController.prototype.loadCatalog = function (reset) {
    var self = this;
    if (!reset && this.state.isLoading) return;
    if (!global.TmdbClient) return;

    this.state.isLoading = true;
    this._catalogRequestId = (this._catalogRequestId || 0) + 1;
    var reqId = this._catalogRequestId;

    var params = {
      page: this.state.currentPage,
      genreId: this.state.activeGenreId,
      sortBy: this.state.activeSortBy,
      year: this.state.activeYear
    };

    return global.TmdbClient.discover(this.mediaType, params).then(function (res) {
      if (reqId !== self._catalogRequestId) return;
      self.state.isLoading = false;
      if (!res || !res.results) {
        if (reset) self.renderEmptyState();
        return;
      }

      self.state.totalPages = res.totalPages || res.total_pages || 1;
      var newItems = res.results;

      if (reset) {
        self.state.items = newItems;
        if (newItems.length === 0) {
          self.renderEmptyState();
        } else {
          self.renderGrid(newItems, true);
        }
      } else {
        self.state.items = self.state.items.concat(newItems);
        self.renderGrid(newItems, false);
      }
    }).catch(function (err) {
      if (reqId !== self._catalogRequestId) return;
      self.state.isLoading = false;
      console.error('[CatalogViewController] Discover failed:', err);
      if (reset) self.renderEmptyState();
    });
  };

  CatalogViewController.prototype.loadMore = function () {
    if (this.state.currentPage < this.state.totalPages && !this.state.isLoading) {
      this.state.currentPage++;
      return this.loadCatalog(false);
    }
    return Promise.resolve();
  };

  CatalogViewController.prototype.renderGrid = function (items, isReset) {
    if (!this.gridContainer) {
      this.gridContainer = this.container ? this.container.querySelector('.content-grid-6col') : null;
    }
    if (!this.gridContainer) return;

    var fragment = document.createDocumentFragment();
    var startIndex = isReset ? 0 : (this.state.items.length - items.length);

    for (var i = 0; i < items.length; i++) {
      var card = CardFactory.createPosterCard(items[i], this.mediaType + '-grid', startIndex + i, {
        mediaType: this.mediaType
      });
      fragment.appendChild(card);
    }

    if (isReset) {
      while (this.gridContainer.firstChild) {
        this.gridContainer.removeChild(this.gridContainer.firstChild);
      }
    }
    this.gridContainer.appendChild(fragment);
  };

  CatalogViewController.prototype.renderEmptyState = function () {
    if (!this.gridContainer) {
      this.gridContainer = this.container ? this.container.querySelector('.content-grid-6col') : null;
    }
    if (!this.gridContainer) return;

    while (this.gridContainer.firstChild) {
      this.gridContainer.removeChild(this.gridContainer.firstChild);
    }

    var emptyMsg = document.createElement('div');
    emptyMsg.className = 'empty-results-message';
    emptyMsg.style.gridColumn = '1 / -1';
    emptyMsg.style.padding = '64px 24px';
    emptyMsg.style.textAlign = 'center';
    emptyMsg.style.color = 'rgba(255, 255, 255, 0.7)';

    var p1 = document.createElement('p');
    p1.style.fontSize = '24px';
    p1.style.fontWeight = '600';
    p1.style.marginBottom = '8px';
    p1.textContent = 'No titles found';
    emptyMsg.appendChild(p1);

    var p2 = document.createElement('p');
    p2.style.fontSize = '16px';
    p2.style.color = 'rgba(255, 255, 255, 0.4)';
    p2.textContent = 'Try adjusting your genre or filter selections.';
    emptyMsg.appendChild(p2);

    this.gridContainer.appendChild(emptyMsg);
  };

  // Expose constructor and instances
  global.CatalogViewController = CatalogViewController;
  global.MoviesViewController = new CatalogViewController('view-movies', 'movie');
  global.SeriesViewController = new CatalogViewController('view-series', 'tv');

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      CatalogViewController: CatalogViewController,
      MoviesViewController: global.MoviesViewController,
      SeriesViewController: global.SeriesViewController
    };
  }

})(typeof window !== 'undefined' ? window : this);

